package cn.hydrogen.launcher;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import java.lang.reflect.*;import java.util.concurrent.*;import org.json.*;
/** Production bridge/control/lifecycle on API19, using two Java test SurfaceViews. */
final class MapRetentionFlow {
 final Instrumentation test;final HandlerThread responses=new HandlerThread("MapRetentionResults");final Handler handler;final String fixture="cn.hydrogen.launcher.test";final StringBuilder report=new StringBuilder("API19 production system-overlay protocol, Java test surfaces; NOT commercial Amap runtime\n");
 MainActivity activity;Config cfg;String backup;AmapFloatingController controller;int passed,failed;Activity internal;
 MapRetentionFlow(Instrumentation t){test=t;responses.start();handler=new Handler(responses.getLooper());}interface Step{void run()throws Exception;}interface Condition{boolean ok()throws Exception;}
 void require(boolean value,String why){if(!value)throw new AssertionError(why);}void main(Runnable r){test.runOnMainSync(r);}Object field(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}
 void check(String title,Step step){android.util.Log.i("MapRetentionTest","START "+title);try{step.run();passed++;report.append("PASS ");}catch(Throwable e){failed++;report.append("FAIL ").append(e).append(" ");}report.append(title).append('\n');if(internal!=null){Activity a=internal;main(a::finish);internal=null;try{await("cleanup return",()->activity.hasWindowFocus());card();}catch(Exception ignored){}}}
 JSONObject state()throws Exception{CountDownLatch latch=new CountDownLatch(1);String[] json={null};test.getTargetContext().sendOrderedBroadcast(new Intent("cn.windchaser.fixture.STATE").setPackage(fixture),null,new BroadcastReceiver(){public void onReceive(Context c,Intent i){json[0]=getResultData();latch.countDown();}},handler,0,null,null);require(latch.await(6,TimeUnit.SECONDS)&&json[0]!=null,"fixture state missing");return new JSONObject(json[0]);}
 void await(String title,Condition c)throws Exception{long end=SystemClock.elapsedRealtime()+10000;while(SystemClock.elapsedRealtime()<end){try{if(c.ok())return;}catch(AssertionError notYet){}Thread.sleep(45);}throw new AssertionError(title+" state="+state()+" controller="+(controller==null?null:controller.status()));}
 void card()throws Exception{await("map visible",()->{JSONObject s=state();return s.optBoolean("bridge_added")&&!s.optBoolean("parked")&&s.optBoolean("surface_valid")&&s.optBoolean("native_resumed")&&controller.connected();});}
 void parked()throws Exception{await("map retained",()->{JSONObject s=state();return s.optBoolean("bridge_added")&&s.optBoolean("parked")&&s.optBoolean("surface_valid")&&(s.optInt("window_flags")&WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE)!=0&&s.optInt("window_x")<-s.optInt("ui_width");});}
 void same(JSONObject a,JSONObject b){for(String n:new String[]{"overlay_identity","surface_created","surface_destroyed","starts","buffer_width","buffer_height"})require(a.optInt(n)==b.optInt(n),n+" changed "+a.optInt(n)+"->"+b.optInt(n));}
 void page(int n){main(()->activity.showPage(n));}
 void external(Class<?> c){test.getTargetContext().startActivity(new Intent().setComponent(new ComponentName(fixture,c.getName())).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));}
 void returnHome()throws Exception{test.getTargetContext().startActivity(new Intent(test.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await("main focused",()->activity.hasWindowFocus());page(MainActivity.CARDS);card();}
 void installTransport()throws Exception{controller=(AmapFloatingController)field(activity,"floatingMap");set(controller,"transport",(AmapFloatingController.Transport)i->test.getTargetContext().sendBroadcast(new Intent(i).setPackage(fixture)));set(controller,"availability",(AmapFloatingController.Availability)()->true);set(controller,"availableAt",-2000L);set(controller,"workspaceFocus",(java.util.concurrent.Callable<Boolean>)()->{boolean yes=MapWorkspace.get(activity).focused();if(!yes){String debug="";try{Object ws=MapWorkspace.get(activity);debug=" external="+field(ws,"external")+" destination="+field(ws,"destination")+" until="+field(ws,"transferUntil")+" now="+SystemClock.uptimeMillis();for(Object entry:((java.util.Map<?,?>)field(ws,"states")).entrySet()){java.util.Map.Entry<?,?> e=(java.util.Map.Entry<?,?>)entry;Activity a=(Activity)e.getKey();debug+=" ["+a.getClass().getSimpleName()+" resumed="+field(e.getValue(),"resumed")+" focus="+a.hasWindowFocus()+" finishing="+a.isFinishing()+"]";}}catch(Exception ignored){}android.util.Log.i("MapRetentionTest","workspace denied"+debug,new Throwable());}return yes;});main(controller::reconnect);card();Thread.sleep(350);}
 void open(Class<? extends Activity> type)throws Exception{main(()->activity.startActivity(new Intent(activity,type)));internal=test.waitForMonitorWithTimeout(test.addMonitor(type.getName(),null,false),1);}
 void ownPage(Class<? extends Activity> type)throws Exception{
  Instrumentation.ActivityMonitor monitor=test.addMonitor(type.getName(),null,false);JSONObject before=state();main(()->activity.startActivity(new Intent(activity,type)));internal=test.waitForMonitorWithTimeout(monitor,10000);test.removeMonitor(monitor);require(internal!=null,"internal activity missing "+type);parked();same(before,state());Thread.sleep(650);same(before,state());Activity a=internal;main(a::finish);internal=null;await("main focus",()->activity.hasWindowFocus());card();same(before,state());
 }
 void run(){try{
  cfg=new Config(test.getTargetContext());backup=cfg.exportJson();cfg.put("autoRecoverApps",false);cfg.put("homePage",MainActivity.CARDS);cfg.put("pageAnimation",false);
  external(com.autonavi.amapauto.MainMapActivity.class);await("fixture resumed",()->!state().optBoolean("paused")&&state().optInt("ui_width")>0);Thread.sleep(600);
  activity=(MainActivity)test.startActivitySync(new Intent(test.getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));Thread.sleep(600);installTransport();
  check("repeated 1/2/3-page switching reuses both surfaces and native connection",()->{JSONObject before=state();for(int n=0;n<4;n++){page(0);parked();same(before,state());page(2);parked();page(1);card();same(before,state());}});
  check("parked map cannot receive touches in its former rectangle",()->{JSONObject before=state();int x=before.optInt("ui_left")+before.optInt("ui_width")/2,y=before.optInt("ui_top")+before.optInt("ui_height")/2;page(0);parked();long now=SystemClock.uptimeMillis();MotionEvent down=MotionEvent.obtain(now,now,0,x,y,0),up=MotionEvent.obtain(now,now+10,1,x,y,0);test.getUiAutomation().injectInputEvent(down,true);test.getUiAutomation().injectInputEvent(up,true);down.recycle();up.recycle();Thread.sleep(100);require(state().optInt("touches")==before.optInt("touches"),"park consumed touch");page(1);card();});
  check("theme settings and their own dialog retain the map",()->{Instrumentation.ActivityMonitor m=test.addMonitor(SettingsActivity.class.getName(),null,false);JSONObject before=state();main(()->activity.startActivity(new Intent(activity,SettingsActivity.class)));internal=test.waitForMonitorWithTimeout(m,10000);test.removeMonitor(m);require(internal!=null,"settings missing");parked();AlertDialog[] dialog={null};Activity a=internal;main(()->{dialog[0]=new ThemeDialog.Builder(a).setTitle("retention check").setItems(new String[]{"one","two"},null).show();});Thread.sleep(800);parked();same(before,state());main(()->{dialog[0].dismiss();a.finish();});internal=null;card();same(before,state());});
  check("weather settings retains map",()->ownPage(WeatherSettingsActivity.class));
  check("file center retains map",()->ownPage(FileCenterActivity.class));
  check("device information retains map",()->ownPage(DeviceInfoActivity.class));
  check("diagnostics retains map",()->ownPage(DiagnosticsActivity.class));
  check("internal application picker keeps visible map and stable surfaces",()->{JSONObject before=state();main(()->Ui.pick(activity,app->{}));Thread.sleep(700);card();same(before,state());Object host=field(activity,"mapDialogs");java.util.Collection<?> owned=(java.util.Collection<?>)field(host,"windows");Dialog d=null;for(Object value:owned){d=(Dialog)field(value,"dialog");if(d.isShowing())break;}require(d!=null,"picker missing");Dialog dialog=d;main(dialog::dismiss);card();same(before,state());});
  check("own dialogs on first and third pages keep the already parked surfaces",()->{JSONObject before=state();for(int n:new int[]{0,2}){page(n);parked();AlertDialog[] dialog={null};main(()->dialog[0]=new ThemeDialog.Builder(activity).setTitle("internal page dialog").setItems(new String[]{"one","two"},null).show());Thread.sleep(650);parked();same(before,state());main(dialog[0]::dismiss);Thread.sleep(650);parked();same(before,state());}page(1);card();same(before,state());});
  check("Activity recreation keeps retained map and drops the old anchor",()->{JSONObject before=state();AmapFloatingController original=controller;View oldAnchor=(View)field(controller,"anchor");MainActivity old=activity;main(old::recreate);await("new MainActivity created",()->{Object ref=field(MapWorkspace.get(test.getTargetContext()),"main");Object value=((java.lang.ref.WeakReference<?>)ref).get();if(value instanceof MainActivity&&value!=old){activity=(MainActivity)value;return true;}return false;});await("new launcher focus",()->activity.hasWindowFocus());controller=(AmapFloatingController)field(activity,"floatingMap");require(controller==original,"controller recreated");card();same(before,state());require(field(controller,"anchor")!=oldAnchor,"old Activity anchor retained");require(old.isDestroyed(),"old Activity not destroyed");});
  check("card width change updates buffer without attaching another window",()->{JSONObject before=state();View anchor=(View)field(controller,"anchor");ViewGroup.LayoutParams params=anchor.getLayoutParams();int width=params.width;main(()->{params.width=anchor.getWidth()-24;anchor.setLayoutParams(params);});await("resized buffer",()->state().optInt("buffer_width")==anchor.getWidth()&&state().optInt("buffer_width")==before.optInt("buffer_width")-24);require(state().optInt("overlay_identity")==before.optInt("overlay_identity"),"resize replaced window");require(state().optInt("starts")==before.optInt("starts"),"resize reinitialized engine");main(()->{params.width=width;anchor.setLayoutParams(params);});await("original buffer restored",()->state().optInt("buffer_width")==before.optInt("buffer_width"));card();});
  check("incoming map follows translation without resize or native re-entry",()->{JSONObject before=state();cfg.put("pageAnimation",true);page(0);parked();main(()->activity.showPage(1));boolean translated=false,moving=false;long until=SystemClock.elapsedRealtime()+1400;while(SystemClock.elapsedRealtime()<until){JSONObject s=state();if(!s.optBoolean("parked")&&s.optInt("window_x")!=before.optInt("window_x"))translated=true;moving|=s.optBoolean("moving");Thread.sleep(12);}card();same(before,state());require(!state().optBoolean("moving"),"touch remained disabled");report.append("animation samples translated=").append(translated).append(" moving=").append(moving).append('\n');require(translated,"no moving window observed");cfg.put("pageAnimation",false);});
  check("full-screen reverse camera removes the overlay",()->{external(ReverseCameraActivity.class);await("camera actually visible",()->{android.view.accessibility.AccessibilityNodeInfo root=test.getUiAutomation().getRootInActiveWindow();if(root==null)return false;try{java.util.List<android.view.accessibility.AccessibilityNodeInfo> nodes=root.findAccessibilityNodeInfosByText("CAMERA PRIORITY TEST");boolean yes=nodes!=null&&!nodes.isEmpty();if(nodes!=null)for(android.view.accessibility.AccessibilityNodeInfo node:nodes)node.recycle();return yes;}finally{root.recycle();}});await("camera overlay removed",()->!state().optBoolean("bridge_added"));returnHome();});
  check("screen-off controller path fully removes retained overlay",()->{page(0);parked();main(()->controller.setScreenOn(false));await("screen off cleanup",()->!state().optBoolean("bridge_added"));main(()->controller.setScreenOn(true));page(1);card();});
  check("host focus denial removes window even while parked",()->{page(0);parked();set(controller,"workspaceFocus",(java.util.concurrent.Callable<Boolean>)()->false);await("focus denial cleanup",()->!state().optBoolean("bridge_added"));main(()->controller.setWorkspaceFocus(MapWorkspace.get(activity)::focused));page(1);card();});
  check("companion without retention capability falls back to full withdrawal",()->{main(()->{try{set(controller,"retentionCapable",false);}catch(Exception e){throw new RuntimeException(e);}activity.showPage(0);});await("legacy fallback cleanup",()->!state().optBoolean("bridge_added"));page(1);card();});
  check("closing launcher removes the map immediately",()->{main(activity::finish);await("finish cleanup",()->!state().optBoolean("bridge_added"));});
 }catch(Throwable e){failed++;report.append("FAIL setup ").append(e).append('\n');}finally{if(internal!=null){Activity a=internal;main(a::finish);}if(activity!=null&&!activity.isFinishing())main(activity::finish);if(backup!=null)try{cfg.restore(backup);}catch(Exception ignored){}}
 report.append("MAP_RETENTION_RESULT passed=").append(passed).append(" failed=").append(failed).append('\n');Bundle out=new Bundle();out.putString("stream",report.toString());responses.quit();test.finish(failed==0?-1:0,out);
 }
}
